  private static void assertJsonEquals(String expected, String actual) throws Exception {
    JsonNode expectedNode = ObjectMappers.JSON_MAPPER.readTree(expected);
    JsonNode actualNode = ObjectMappers.JSON_MAPPER.readTree(actual);
    assertTrue(
      expectedNode.equals(NUMERIC_EQUIVALENCE, actualNode),
      () -> "expected: " + expected + " but was: " + actual
    );
  }
